insert into famous_verses (ord, slug, book, chapter, verse_start, verse_end, reference, theme, title, blurb, verse_text) values
(0, 'jean-3-16', 43, 3, 16, 16, 'Jean 3.16', 'L''amour de Dieu', 'Le cœur de l''Évangile', 'Sans doute le verset le plus connu au monde : Dieu aime, Dieu donne, et la vie éternelle s''ouvre à quiconque croit. Tout l''Évangile en une phrase.', 'Car Dieu a tant aimé le monde qu''il a donné son Fils unique, afin que quiconque croit en lui ne périsse point, mais qu''il ait la vie éternelle.'),
(1, 'genese-1-1', 1, 1, 1, 1, 'Genèse 1.1', 'La création', 'Au commencement', 'La première phrase de la Bible : Dieu est là avant tout, et tout vient de lui. Le fondement de toute la foi.', 'Au commencement, Dieu créa les cieux et la terre.'),
(2, 'psaume-23-1', 19, 23, 1, 1, 'Psaume 23.1', 'La confiance', 'Le Seigneur est mon berger', 'Le psaume le plus aimé : Dieu conduit, nourrit et protège comme un berger. L''image de la confiance paisible au milieu de tout.', 'L''Éternel est mon berger : je ne manquerai de rien.'),
(3, 'jean-14-6', 43, 14, 6, 6, 'Jean 14.6', 'L''identité de Christ', 'Le chemin, la vérité, la vie', 'L''une des sept déclarations « Je suis » de Jésus : il ne montre pas seulement le chemin, il est le chemin vers le Père.', 'Jésus lui dit : Je suis le chemin, la vérité, et la vie. Nul ne vient au Père que par moi.'),
(4, 'romains-8-28', 45, 8, 28, 28, 'Romains 8.28', 'La confiance', 'Tout concourt au bien', 'La promesse qui soutient dans l''épreuve : rien n''est perdu, Dieu tisse même le mal pour le bien de ceux qui l''aiment.', 'Nous savons, du reste, que toutes choses concourent au bien de ceux qui aiment Dieu, de ceux qui sont appelés selon son dessein.'),
(5, 'philippiens-4-13', 50, 4, 13, 13, 'Philippiens 4.13', 'La force et le courage', 'Je puis tout par Christ', 'Non un slogan de performance, mais le secret de Paul en prison : une force qui vient d''un Autre, dans l''abondance comme dans le manque.', 'Je puis tout par celui qui me fortifie.'),
(6, 'proverbes-3-5', 20, 3, 5, 6, 'Proverbes 3.5-6', 'La sagesse et la conduite', 'Confie-toi en l''Éternel', 'La sagesse pratique par excellence : lâcher la maîtrise, faire confiance à Dieu plutôt qu''à sa propre intelligence, et le laisser diriger.', 'Confie-toi en l''Éternel de tout ton cœur, et ne t''appuie pas sur ta sagesse ; reconnais-le dans toutes tes voies, et il aplanira tes sentiers.'),
(7, 'romains-3-23', 45, 3, 23, 23, 'Romains 3.23', 'Le salut et la grâce', 'Tous ont péché', 'Le diagnostic universel : personne n''est à la hauteur par lui-même. Le point de départ obligé pour comprendre la grâce.', 'Car tous ont péché et sont privés de la gloire de Dieu.'),
(8, 'romains-6-23', 45, 6, 23, 23, 'Romains 6.23', 'Le salut et la grâce', 'Le don gratuit de Dieu', 'En une phrase, le contraste total : ce que le péché paie (la mort) et ce que Dieu offre gratuitement (la vie éternelle en Christ).', 'Car le salaire du péché, c''est la mort ; mais le don gratuit de Dieu, c''est la vie éternelle en Jésus-Christ notre Seigneur.'),
(9, 'ephesiens-2-8', 49, 2, 8, 9, 'Éphésiens 2.8-9', 'Le salut et la grâce', 'Sauvés par grâce', 'Le pilier de la Réforme : le salut n''est pas un salaire mais un cadeau, reçu par la foi, pour que personne ne se glorifie.', 'Car c''est par la grâce que vous êtes sauvés, par le moyen de la foi. Et cela ne vient pas de vous, c''est le don de Dieu. Ce n''est point par les œuvres, afin que personne ne se glorifie.'),
(10, 'jeremie-29-11', 24, 29, 11, 11, 'Jérémie 29.11', 'L''espérance et l''éternité', 'Des projets de paix', 'Une promesse née en plein exil : même quand tout semble sombre, Dieu prépare un avenir et une espérance.', 'Car je connais les projets que j''ai formés sur vous, dit l''Éternel, projets de paix et non de malheur, afin de vous donner un avenir et de l''espérance.'),
(11, 'esaie-41-10', 23, 41, 10, 10, 'Ésaïe 41.10', 'La paix et l''inquiétude', 'Ne crains rien', 'L''antidote à la peur : non « sois fort », mais « je suis avec toi ». La présence de Dieu comme remède à l''angoisse.', 'Ne crains rien, car je suis avec toi ; ne promène pas des regards inquiets, car je suis ton Dieu ; je te fortifie, je viens à ton secours, je te soutiens de ma droite triomphante.'),
(12, 'matthieu-6-33', 40, 6, 33, 33, 'Matthieu 6.33', 'La sagesse et la conduite', 'Cherchez d''abord le Royaume', 'La clé des priorités : mettre Dieu à la première place, et laisser le reste à sa providence.', 'Cherchez premièrement le royaume et la justice de Dieu ; et toutes ces choses vous seront données par-dessus.'),
(13, 'galates-2-20', 48, 2, 20, 20, 'Galates 2.20', 'L''identité en Christ', 'Christ vit en moi', 'Le cœur de la vie chrétienne : non plus moi qui m''efforce, mais Christ qui vit en moi par la foi.', 'J''ai été crucifié avec Christ ; et si je vis, ce n''est plus moi qui vis, c''est Christ qui vit en moi ; si je vis maintenant dans la chair, je vis dans la foi au Fils de Dieu, qui m''a aimé et qui s''est livré lui-même pour moi.'),
(14, 'romains-12-2', 45, 12, 2, 2, 'Romains 12.2', 'La sagesse et la conduite', 'Ne vous conformez pas au monde', 'Un appel à la transformation intérieure plutôt qu''à suivre le moule du monde : c''est l''esprit renouvelé qui discerne la volonté de Dieu.', 'Ne vous conformez pas au siècle présent, mais soyez transformés par le renouvellement de l''intelligence, afin que vous discerniez quelle est la volonté de Dieu, ce qui est bon, agréable et parfait.'),
(15, '1corinthiens-13-4', 46, 13, 4, 7, '1 Corinthiens 13.4-7', 'L''amour de Dieu', 'L''hymne à l''amour', 'La définition la plus célèbre de l''amour : patient, sans orgueil, il supporte tout et ne cherche pas son intérêt. Lu à d''innombrables mariages.', 'La charité est patiente, elle est pleine de bonté ; la charité n''est point envieuse ; la charité ne se vante point, elle ne s''enfle point d''orgueil, elle ne fait rien de malhonnête, elle ne cherche point son intérêt, elle ne s''irrite point, elle ne soupçonne point le mal, elle ne se réjouit point de l''injustice, mais elle se réjouit de la vérité ; elle excuse tout, elle croit tout, elle espère tout, elle supporte tout.'),
(16, 'psaume-46-2', 19, 46, 2, 2, 'Psaume 46.2', 'La paix et l''inquiétude', 'Un refuge et une force', 'Le verset qui a inspiré le cantique de Luther : quand tout tremble, Dieu reste l''abri assuré.', 'Dieu est pour nous un refuge et un appui, un secours qui ne manque jamais dans la détresse.'),
(17, 'josue-1-9', 6, 1, 9, 9, 'Josué 1.9', 'La force et le courage', 'Fortifie-toi et prends courage', 'L''ordre donné à Josué au seuil de l''inconnu : le courage repose non sur soi, mais sur la présence de Dieu qui accompagne partout.', 'Ne t''ai-je pas donné cet ordre : Fortifie-toi et prends courage ? Ne t''effraie point et ne t''épouvante point, car l''Éternel, ton Dieu, est avec toi dans tout ce que tu entreprendras.'),
(18, 'philippiens-4-6', 50, 4, 6, 7, 'Philippiens 4.6-7', 'La paix et l''inquiétude', 'Ne vous inquiétez de rien', 'Le remède à l''anxiété : tout remettre à Dieu par la prière, et recevoir une paix qui dépasse la raison.', 'Ne vous inquiétez de rien ; mais en toute chose faites connaître vos besoins à Dieu par des prières et des supplications, avec des actions de grâces. Et la paix de Dieu, qui surpasse toute intelligence, gardera vos cœurs et vos pensées en Jésus-Christ.'),
(19, '2timothee-1-7', 55, 1, 7, 7, '2 Timothée 1.7', 'La force et le courage', 'Un esprit de force', 'Contre la peur qui paralyse : Dieu donne force, amour et maîtrise de soi. Un verset d''aplomb pour les timides.', 'Car ce n''est pas un esprit de timidité que Dieu nous a donné, mais un esprit de force, d''amour et de sagesse.'),
(20, 'romains-10-9', 45, 10, 9, 9, 'Romains 10.9', 'Le salut et la grâce', 'Confesser et croire', 'La porte du salut, simple et directe : reconnaître Jésus comme Seigneur et croire en sa résurrection.', 'Si tu confesses de ta bouche le Seigneur Jésus, et si tu crois dans ton cœur que Dieu l''a ressuscité des morts, tu seras sauvé.'),
(21, 'jean-1-1', 43, 1, 1, 1, 'Jean 1.1', 'L''identité de Christ', 'Au commencement était la Parole', 'L''ouverture vertigineuse de Jean : avant la création, la Parole était, était avec Dieu, et était Dieu. La divinité de Christ affirmée d''emblée.', 'Au commencement était la Parole, et la Parole était avec Dieu, et la Parole était Dieu.'),
(22, 'matthieu-28-19', 40, 28, 19, 20, 'Matthieu 28.19-20', 'La mission', 'Faites de toutes les nations des disciples', 'Les derniers mots de Jésus, la « grande mission » : aller vers tous, baptiser, enseigner — avec la promesse de sa présence.', 'Allez, faites de toutes les nations des disciples, les baptisant au nom du Père, du Fils et du Saint-Esprit, et enseignez-leur à observer tout ce que je vous ai prescrit. Et voici, je suis avec vous tous les jours, jusqu''à la fin du monde.'),
(23, 'actes-1-8', 44, 1, 8, 8, 'Actes 1.8', 'La mission', 'Vous recevrez une puissance', 'La promesse qui lance l''Église : l''Esprit donne la force du témoignage, de Jérusalem jusqu''au bout du monde.', 'Mais vous recevrez une puissance, le Saint-Esprit survenant sur vous, et vous serez mes témoins à Jérusalem, dans toute la Judée, dans la Samarie, et jusqu''aux extrémités de la terre.'),
(24, 'hebreux-11-1', 58, 11, 1, 1, 'Hébreux 11.1', 'La foi et la confiance', 'La définition de la foi', 'La foi définie : une assurance et une conviction touchant l''invisible. Le socle de tout le « panthéon » des héros de la foi.', 'Or la foi est une ferme assurance des choses qu''on espère, une démonstration de celles qu''on ne voit pas.'),
(25, 'romains-5-8', 45, 5, 8, 8, 'Romains 5.8', 'L''amour de Dieu', 'Christ est mort pour nous', 'La preuve suprême de l''amour de Dieu : non que nous étions bons, mais qu''il est mort pour nous alors que nous étions encore pécheurs.', 'Mais Dieu prouve son amour envers nous, en ce que, lorsque nous étions encore des pécheurs, Christ est mort pour nous.'),
(26, '1jean-1-9', 62, 1, 9, 9, '1 Jean 1.9', 'Le salut et la grâce', 'Il pardonne et purifie', 'L''assurance du pardon : à qui reconnaît ses fautes, Dieu est fidèle pour pardonner et purifier entièrement.', 'Si nous confessons nos péchés, il est fidèle et juste pour nous les pardonner, et pour nous purifier de toute iniquité.'),
(27, 'psaume-119-105', 19, 119, 105, 105, 'Psaume 119.105', 'La sagesse et la conduite', 'Une lampe à mes pieds', 'L''image la plus connue de la Parole : elle éclaire juste assez pour le pas suivant, comme une lampe sur un sentier de nuit.', 'Ta parole est une lampe à mes pieds, et une lumière sur mon sentier.'),
(28, 'esaie-53-5', 23, 53, 5, 5, 'Ésaïe 53.5', 'Le salut et la grâce', 'Par ses meurtrissures', 'Sept siècles avant la croix, la substitution décrite avec précision : blessé à notre place, il nous apporte paix et guérison.', 'Mais il était blessé pour nos péchés, brisé pour nos iniquités ; le châtiment qui nous donne la paix est tombé sur lui, et c''est par ses meurtrissures que nous sommes guéris.'),
(29, 'matthieu-11-28', 40, 11, 28, 30, 'Matthieu 11.28-30', 'La paix et l''inquiétude', 'Venez à moi', 'L''invitation la plus douce de Jésus aux épuisés : venir à lui, prendre son joug, et trouver le repos de l''âme.', 'Venez à moi, vous tous qui êtes fatigués et chargés, et je vous donnerai du repos. Prenez mon joug sur vous et recevez mes instructions, car je suis doux et humble de cœur ; et vous trouverez du repos pour vos âmes.'),
(30, 'jean-10-10', 43, 10, 10, 10, 'Jean 10.10', 'L''identité de Christ', 'La vie en abondance', 'Le contraste entre le voleur et le berger : Jésus n''est pas venu réduire la vie, mais la donner pleine et débordante.', 'Le voleur ne vient que pour dérober, égorger et détruire ; moi, je suis venu afin que les brebis aient la vie, et qu''elles soient dans l''abondance.'),
(31, 'romains-8-38', 45, 8, 38, 39, 'Romains 8.38-39', 'L''amour de Dieu', 'Rien ne nous séparera', 'Le sommet de Romains 8 : aucune puissance, aucune épreuve, ni la mort ni la vie ne peuvent nous arracher à l''amour de Dieu en Christ.', 'Car j''ai l''assurance que ni la mort ni la vie, ni les anges ni les dominations, ni les choses présentes ni les choses à venir, ni les puissances, ni la hauteur, ni la profondeur, ni aucune autre créature ne pourra nous séparer de l''amour de Dieu manifesté en Jésus-Christ notre Seigneur.'),
(32, '2corinthiens-5-17', 47, 5, 17, 17, '2 Corinthiens 5.17', 'L''identité en Christ', 'Une nouvelle création', 'La nouveauté radicale du salut : uni à Christ, on ne se répare pas, on devient une création nouvelle.', 'Si quelqu''un est en Christ, il est une nouvelle créature. Les choses anciennes sont passées ; voici, toutes choses sont devenues nouvelles.'),
(33, 'galates-5-22', 48, 5, 22, 23, 'Galates 5.22-23', 'La sagesse et la conduite', 'Le fruit de l''Esprit', 'Le portrait de la vie transformée : non des efforts isolés, mais un fruit que l''Esprit fait mûrir — amour, joie, paix…', 'Mais le fruit de l''Esprit, c''est l''amour, la joie, la paix, la patience, la bonté, la bénignité, la fidélité, la douceur, la tempérance.'),
(34, 'michee-6-8', 33, 6, 8, 8, 'Michée 6.8', 'La sagesse et la conduite', 'Ce que l''Éternel demande', 'Le résumé prophétique de la vraie religion : la justice, la bonté et l''humilité, plutôt que les rites extérieurs.', 'On t''a fait connaître, ô homme, ce qui est bien ; et ce que l''Éternel demande de toi, c''est que tu pratiques la justice, que tu aimes la miséricorde, et que tu marches humblement avec ton Dieu.'),
(35, 'esaie-40-31', 23, 40, 31, 31, 'Ésaïe 40.31', 'La force et le courage', 'De nouvelles forces', 'La promesse aux épuisés qui s''appuient sur Dieu : des forces renouvelées, une endurance donnée d''en haut.', 'Mais ceux qui se confient en l''Éternel renouvellent leur force. Ils prennent le vol comme les aigles ; ils courent, et ne se lassent point, ils marchent, et ne se fatiguent point.'),
(36, 'lamentations-3-22', 25, 3, 22, 23, 'Lamentations 3.22-23', 'L''espérance et l''éternité', 'Nouvelles chaque matin', 'Au fond du deuil, une lumière : les compassions de Dieu ne s''épuisent pas, elles se renouvellent chaque matin.', 'Les bontés de l''Éternel ne sont pas épuisées, ses compassions ne sont pas à leur terme ; elles se renouvellent chaque matin. Grande est ta fidélité.'),
(37, 'psaume-139-14', 19, 139, 14, 14, 'Psaume 139.14', 'La création', 'Formé de façon admirable', 'L''émerveillement devant la création de soi-même : chacun est l''œuvre soignée et voulue de Dieu, non un hasard.', 'Je te loue de ce que je suis une créature si merveilleuse. Tes œuvres sont admirables, et mon âme le reconnaît bien.'),
(38, 'matthieu-5-16', 40, 5, 16, 16, 'Matthieu 5.16', 'La sagesse et la conduite', 'Que votre lumière brille', 'La vocation du disciple : vivre de telle sorte que le bien visible ramène la gloire à Dieu, non à soi.', 'Que votre lumière luise ainsi devant les hommes, afin qu''ils voient vos bonnes œuvres, et qu''ils glorifient votre Père qui est dans les cieux.'),
(39, 'apocalypse-21-4', 66, 21, 4, 4, 'Apocalypse 21.4', 'L''espérance et l''éternité', 'Plus de larmes', 'La promesse finale de la Bible : un monde où Dieu essuie toute larme, où la mort et la douleur ont disparu.', 'Il essuiera toute larme de leurs yeux, et la mort ne sera plus, et il n''y aura plus ni deuil, ni cri, ni douleur, car les premières choses ont disparu.'),
(40, 'apocalypse-3-20', 66, 3, 20, 20, 'Apocalypse 3.20', 'L''amour de Dieu', 'Je me tiens à la porte', 'L''image tendre du Christ qui frappe et attend : il n''enfonce pas la porte, il demande à entrer et partager le repas.', 'Voici, je me tiens à la porte, et je frappe. Si quelqu''un entend ma voix et ouvre la porte, j''entrerai chez lui, je souperai avec lui, et lui avec moi.'),
(41, 'jean-8-12', 43, 8, 12, 12, 'Jean 8.12', 'L''identité de Christ', 'La lumière du monde', 'Une autre déclaration « Je suis » : suivre Jésus, c''est marcher hors des ténèbres, dans la lumière de la vie.', 'Jésus leur parla de nouveau, et dit : Je suis la lumière du monde ; celui qui me suit ne marchera pas dans les ténèbres, mais il aura la lumière de la vie.'),
(42, 'matthieu-22-37', 40, 22, 37, 39, 'Matthieu 22.37-39', 'La sagesse et la conduite', 'Le plus grand commandement', 'Toute la Loi ramassée en deux amours : Dieu de tout son être, et le prochain comme soi-même.', 'Tu aimeras le Seigneur, ton Dieu, de tout ton cœur, de toute ton âme, et de toute ta pensée. C''est le premier et le plus grand commandement. Et voici le second, qui lui est semblable : Tu aimeras ton prochain comme toi-même.'),
(43, 'psaume-27-1', 19, 27, 1, 1, 'Psaume 27.1', 'La force et le courage', 'Ma lumière et mon salut', 'Un cri de confiance qui dissout la peur : si Dieu est lumière, salut et forteresse, qui redouter ?', 'L''Éternel est ma lumière et mon salut : de qui aurais-je crainte ? L''Éternel est le soutien de ma vie : de qui aurais-je peur ?'),
(44, 'psaume-91-1', 19, 91, 1, 2, 'Psaume 91.1-2', 'La paix et l''inquiétude', 'À l''ombre du Tout-Puissant', 'Le psaume de la protection : demeurer sous l''abri de Dieu comme sous une aile, en sécurité au milieu du danger.', 'Celui qui demeure sous l''abri du Très-Haut repose à l''ombre du Tout-Puissant. Je dis à l''Éternel : Mon refuge et ma forteresse, mon Dieu en qui je me confie !'),
(45, 'proverbes-16-3', 20, 16, 3, 3, 'Proverbes 16.3', 'La sagesse et la conduite', 'Recommande à l''Éternel tes œuvres', 'La sagesse de remettre ses projets à Dieu avant d''agir : lui confier l''ouvrage pour que les plans tiennent.', 'Recommande à l''Éternel tes œuvres, et tes projets réussiront.'),
(46, 'jacques-1-5', 59, 1, 5, 5, 'Jacques 1.5', 'La sagesse et la conduite', 'Demandez la sagesse', 'Une invitation simple : quand on manque de sagesse, la demander à Dieu qui donne à tous largement, sans reproche.', 'Si quelqu''un d''entre vous manque de sagesse, qu''il la demande à Dieu, qui donne à tous simplement et sans reproche, et elle lui sera donnée.'),
(47, '1pierre-5-7', 60, 5, 7, 7, '1 Pierre 5.7', 'La paix et l''inquiétude', 'Déchargez-vous sur lui', 'Le geste de la confiance : jeter toute son inquiétude sur Dieu, parce qu''il prend soin de nous.', 'et déchargez-vous sur lui de tous vos soucis, car lui-même prend soin de vous.'),
(48, 'psaume-37-4', 19, 37, 4, 4, 'Psaume 37.4', 'La foi et la confiance', 'Fais de l''Éternel tes délices', 'Quand Dieu devient la joie du cœur, les désirs eux-mêmes s''ajustent et trouvent leur accomplissement en lui.', 'Fais de l''Éternel tes délices, et il te donnera ce que ton cœur désire.'),
(49, 'colossiens-3-23', 51, 3, 23, 23, 'Colossiens 3.23', 'La sagesse et la conduite', 'Travaillez pour le Seigneur', 'Une consécration du quotidien : quoi que l''on fasse, le faire de tout cœur comme pour Dieu, non pour les hommes.', 'Tout ce que vous faites, faites-le de bon cœur, comme pour le Seigneur et non pour des hommes.'),
(50, 'deuteronome-31-6', 5, 31, 6, 6, 'Deutéronome 31.6', 'La force et le courage', 'Il ne te délaissera point', 'L''encouragement au seuil du combat : le courage repose sur une promesse — Dieu marche avec toi et ne t''abandonne pas.', 'Fortifiez-vous et ayez du courage ! Ne craignez point et ne soyez point effrayés devant eux ; car l''Éternel, ton Dieu, marchera lui-même avec toi, il ne te délaissera point, il ne t''abandonnera point.'),
(51, 'psaume-46-11', 19, 46, 11, 11, 'Psaume 46.11', 'La paix et l''inquiétude', 'Cessez, et sachez', 'Un appel au calme au milieu du tumulte : arrêter l''agitation pour reconnaître qui est Dieu.', 'Arrêtez, et sachez que je suis Dieu : je domine sur les nations, je domine sur la terre.'),
(52, 'jean-15-5', 43, 15, 5, 5, 'Jean 15.5', 'L''identité en Christ', 'Le cep et les sarments', 'L''image de la vie unie à Christ : sans lui on ne peut rien, en lui on porte beaucoup de fruit.', 'Je suis le cep, vous êtes les sarments. Celui qui demeure en moi et en qui je demeure porte beaucoup de fruit, car sans moi vous ne pouvez rien faire.'),
(53, '2corinthiens-12-9', 47, 12, 9, 9, '2 Corinthiens 12.9', 'La force et le courage', 'Ma grâce te suffit', 'Le renversement de la faiblesse : c''est justement là que la puissance de Christ se déploie le mieux.', 'et il m''a dit : Ma grâce te suffit, car ma puissance s''accomplit dans la faiblesse. Je me glorifierai donc bien plus volontiers de mes faiblesses, afin que la puissance de Christ repose sur moi.'),
(54, 'romains-12-12', 45, 12, 12, 12, 'Romains 12.12', 'L''espérance et l''éternité', 'Joyeux dans l''espérance', 'Trois appuis pour tenir : se réjouir dans l''espérance, tenir bon dans l''épreuve, persévérer dans la prière.', 'Réjouissez-vous en espérance. Soyez patients dans l''affliction. Persévérez dans la prière.'),
(55, 'psaume-34-9', 19, 34, 9, 9, 'Psaume 34.9', 'La foi et la confiance', 'Goûtez et voyez', 'Une invitation à l''expérience : ne pas seulement croire de loin, mais goûter combien Dieu est bon.', 'Sentez et voyez combien l''Éternel est bon ! Heureux l''homme qui cherche en lui son refuge !')
