-- Les versets les plus connus et importants du christianisme.
-- Texte : Louis Segond 1910 (domaine public). book = books.id (1-66).

create table if not exists famous_verses (
  slug text primary key,
  ord int not null default 0,
  book int not null,
  chapter int not null,
  verse_start int not null,
  verse_end int not null,
  reference text not null,
  theme text not null,
  title text not null,
  blurb text not null,
  verse_text text not null,
  created_at timestamptz not null default now()
);
create index if not exists famous_verses_loc_idx on famous_verses (book, chapter);
alter table famous_verses enable row level security;
drop policy if exists famous_verses_read on famous_verses;
create policy famous_verses_read on famous_verses for select using (true);

on conflict (slug) do update set
  ord=excluded.ord, book=excluded.book, chapter=excluded.chapter,
  verse_start=excluded.verse_start, verse_end=excluded.verse_end, reference=excluded.reference,
  theme=excluded.theme, title=excluded.title, blurb=excluded.blurb, verse_text=excluded.verse_text;
